+				}
+				egressPorts = append(egressPorts, networkingv1.NetworkPolicyPort{
+					Protocol: &proto,
+					Port:     &portNum,
+				})
+			}
+			egressRules = append(egressRules, networkingv1.NetworkPolicyEgressRule{
+				To:    egressPeers,
+				Ports: egressPorts,
+			})
